type Category = "inbox" | "today";
export const forceCategory = (rawText: string): Category => {
  return rawText as Category;
};

export const parseResponseUnsafely = async <T>(response: Response): Promise<T> => {
  const parsed = await response.json();
  return parsed as T;
};

interface User { readonly id: string }
declare const raw: unknown;
export const user = <User>raw;

